import{d as c,C as t,o as m,c as u,j as a,a as o,E as r,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第四十七章","description":"循王弼事有宗、物有主，理解不出户知天下与不为而成。","frontmatter":{"title":"道德经第四十七章","description":"循王弼事有宗、物有主，理解不出户知天下与不为而成。","category":"guide","aliases":["道德经第四十七章","老子第四十七章","dao de jing chapter 47"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-47.md","filePath":"daoism/dao-de-jing/chapter-47.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-47.md"},k=c({...p,setup(g){const i=[{id:"root-without-going-out",label:"不出户，知天下",showLabel:!0,sentences:[["不出户，知天下；不",{text:"窥",glossary:"kui"},{text:"牖",glossary:"you-window"},"，见",{text:"天道",glossary:"tiandao"},"。"]],note:["【白话】不走出门户，也可以知道天下之理；不从窗口向外窥看，也可以认识天道。依王弼，这样的知与见，着眼于事物共同的根本与常理。","【王弼注择要】「事有宗而物有主，途虽殊而同归也，虑虽百而其致一也。」又说「道有大常，理有大致」，先交代为何可以由共同所依来理解变化。","【读法】户为门，牖为窗。这里不把知天下解释为闭门即可知道全部具体事实；王弼讨论的根本之理，与现实判断所需的观察和核实须分清。"]},{id:"distance-from-the-root",label:"其出弥远，其知弥少",showLabel:!0,sentences:[["其出",{text:"弥",glossary:"mi"},"远，其知",{text:"弥",glossary:"mi"},"少。"]],note:["【白话】这样向外追逐得越远，所真正知道的反而越少。这里承接前段，所失去的是贯通纷多事物的根本。","【王弼注择要】「无在于一而求之于众也。」注又以「出愈远愈迷也」说明：若不识所由，只在外物中逐求，越追越可能迷失。","【读法】弥即愈、更加。这不是旅程与知识量之间的普遍反比公式；针对的是舍本逐末的求知方式，不能据此拒绝调查、交流和学习。"]},{id:"knowing-and-naming",label:"不行而知，不见而名",showLabel:!0,sentences:[["是以圣人不行而知，不见而",{text:"名",glossary:"ming"},"，"]],note:["【白话】所以圣人不必逐一亲自前往，便能推知事理；不必逐件亲眼见到，也能辨识、称说其所以然。","【王弼注择要】「得物之致，故虽不行而虑可知也。」又说「识物之宗，故虽不见而是非之理可得而名也」，将不行、不见都落在识其宗致。","【读法】名在这里按辨识、判明并称说来读，与第四十四章的声名分义。能由根本推知事理，不表示每次推断都自动正确；具体判断仍应容许事实检验。"]},{id:"completion-through-nature",label:"不为而成",showLabel:!0,sentences:[["不",{text:"为",glossary:"wei"},"而成。"]],note:["【白话】不凭自己的意图强作，事情仍得以成就。这不是凭空等候，而是明白事物本有的性质，顺着它来成全。","【王弼注择要】「明物之性，因之而已，故虽不为而使之成矣。」注用明性、因性说明成的条件。","【读法】这一句接在不行而知、不见而名之后，使知不只停留于概念。若没有理解条件，只把不为当作不处理，便与王注因之的意思有别。"]}],n=[{id:"kui",term:"窥",sense:1},{id:"you-window",term:"牖",sense:1},{id:"tiandao",term:"天道",sense:1},{id:"mi",term:"弥",sense:1},{id:"ming",term:"名",sense:4},{id:"wei",term:"为",sense:1,context:"本句循明物之性、因之而已解释不强作，不泛指取消所有行动。"}];return(x,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return m(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第四十七章",tabindex:"-1"},[o("道德经第四十七章 "),a("a",{class:"header-anchor",href:"#道德经第四十七章","aria-label":'Permalink to "道德经第四十七章"'},"​")],-1)),r(s,{title:"不出户知天下，要把握的是什么",summary:"本章从不出户、不窥牖说到不行而知、不见而名、不为而成。王弼的解释以事有宗、物有主为起点：不在纷多外逐中失去根本，并以明物之性、因之而已说明成事。",points:[{label:"先读",text:"不出户并非可以凭空知道所有事实，先看王弼所说共同的根本与常理。"},{label:"再辨",text:"弥远弥少针对离一求众的外逐，不把出行、调查和学习本身当作错误。"},{label:"后看",text:"不见而名的名在此作辨识称说；不为而成依物性成全，仍有回应。"}],hint:"窥读 kuī，牖读 yǒu，弥读 mí；不见而名保留名字，循王弼是非之理可得而名解释。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:i,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"不出户，知天下；不窥牖，见天道。",tone:"由共同根本理解变化",guide:"循事有宗而物有主读知天下，不推成闭门可知所有事实。"},{text:"其出弥远，其知弥少。",tone:"离本外逐的代价",guide:"弥远弥少反省求知方式，保留观察与核实的必要。"},{text:"不为而成。",tone:"明性而因之",guide:"知其所以然，才能减少无谓强作而帮助成事。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:n}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-三组不字怎样彼此衔接" tabindex="-1">象：三组不字怎样彼此衔接？ <a class="header-anchor" href="#象-三组不字怎样彼此衔接" aria-label="Permalink to &quot;象：三组不字怎样彼此衔接？&quot;">​</a></h3><p>不出户、不窥牖先提出认识的可能，不行而知、不见而名再以圣人说明，末句转入不为而成。王弼以识根本、明物性贯通认识与成事。</p><h3 id="理-为什么搜求更多-反而可能更不明白" tabindex="-1">理：为什么搜求更多，反而可能更不明白？ <a class="header-anchor" href="#理-为什么搜求更多-反而可能更不明白" aria-label="Permalink to &quot;理：为什么搜求更多，反而可能更不明白？&quot;">​</a></h3><p>若只增加零散见闻，却不问它们因何成立，材料会越来越多，联系却越来越弱。王弼所批评的无在于一而求之于众，正是这种离开根本的外逐。</p><h3 id="用-今天怎样借鉴而不陷入凭空推演" tabindex="-1">用：今天怎样借鉴而不陷入凭空推演？ <a class="header-anchor" href="#用-今天怎样借鉴而不陷入凭空推演" aria-label="Permalink to &quot;用：今天怎样借鉴而不陷入凭空推演？&quot;">​</a></h3><p>先提出能贯通现象的解释，再用实际观察检验它是否成立。根本之论可以帮助组织经验，但现代应用中的事实检验是我们的实践方法，不能冒充原注已有的科学程序。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>为见闻找到问题。</strong> 阅读、出行和调查之前，先说清要理解什么；完成后再把发现与原来的判断对照。信息量增加，才可能成为理解的增加。</p><p><strong>先理解条件，再决定如何做。</strong> 事情推进不动时，先看限制和已有能力，减少与物性、条件相冲突的强推。不为而成可以启发这种做法，也仍需要负责的行动。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我最近积累的见闻，是否帮助我认清了一个共同问题？我所谓的根本判断，有哪些事实可以支持，又有哪些事实可能改变它？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文与标点沿本站保留，据卷三 009a–009b 电子录文核对；窥对应录文闚，不见而名保留名字。</li><li>名新增辨识、判明并称说义，依王弼是非之理可得而名释读，不套用命名概念或声名义。</li><li>王注以事有宗、物有主和因物之性解释；本站对调查、事实检验的说明属于阅读边界与现代启发，不混作古注原话。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_003.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷三 HFL 本电子录文，009a–009b</a>。</p>',15))])}}});export{_ as __pageData,k as default};
